  "prediction_basis_card_ids": ["C01", "C13", "C24", "C31", "C38", "C12"],
  "claims": [
    {
      "claim": "EM574, a closely related macrolide, has very low human oral bioavailability (~2%) inferred from a mean oral CL/F of 4500 L/h, with low F also in rabbits (2.4–3.3% FgFh) and rats/dogs; this is the most transferable direct F evidence for the query macrolide.",
      "card_ids": ["C01", "C13", "C24", "C31", "C38"]
    },
    {
      "claim": "YH4808 provides a direct human absolute F of 10.1% (range 2.3–19.3%), below the 20% threshold, though it is structurally distant from the query.",
      "card_ids": ["C12"]
    },
    {
      "claim": "L4 absorption/permeability records for other macrolides are mixed: tacrolimus has low aqueous solubility (~10 µg/mL) but high estimated Peff (4.77×10−4 cm/s); erythromycin acistrate is adequately absorbed and erythromycin shows high MDCK permeability under P-gp inhibition. These records do not report F and do not override the direct low-F macrolide evidence.",
      "card_ids": ["C54", "C56", "C57", "C59", "C62", "C63"]
    },
    {
      "claim": "Clarithromycin Cmax records (3.65 and 3.12 µg/mL at 500 mg BID) show oral exposure for a macrolide but no F, so they cannot establish threshold-relevant bioavailability.",
      "card_ids": ["C41", "C47"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C54", "C56", "C57", "C59", "C62", "C63"]
    }
  ],
  "evidence_gaps": [
    "No direct human absolute F measurement exists for the exact query macrolide.",
    "EM574 is closely related but not identical; differences in sugar substitution, absence of HBD, and aglycone may alter absorption or metabolism.",
    "L4 permeability/solubility data are for other macrolides (tacrolimus, erythromycin) and specific formulations, not for the query.",
    "No quantitative solubility, permeability, or metabolic stability data for the query were supplied.",
    "Formulation, food effects, and first-pass enzyme contributions for the query are unknown."
  ],
  "decision_summary": "Prediction remains low: the most transferable direct F evidence is EM574, a closely related macrolide with ~2% human F and low F in rabbits/rats/dogs; YH4808 adds a direct human F of 10.1%. L4 absorption/permeability records for other macrolides are mixed and indirect, showing low solubility but high permeability in some cases, but they do not provide F and do not overturn the low-F macrolide evidence. Confidence remains moderate."
}

